// Lambda (C++14 generic)
auto betweenL = [low, high](const auto& val) { return low <= val && val <= high; };

// std::bind equivalent (Obscure)
auto betweenB = std::bind(std::logical_and<>(), 
              std::bind(std::less_equal<>(), low, _1),
              std::bind(std::less_equal<>(), _1, high));
